create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, currency text not null default 'EUR', created_at timestamptz not null default now());
create table if not exists public.accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, kind text not null, balance numeric(14,2) not null default 0, currency text not null default 'EUR', created_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, name text not null, kind text not null, created_at timestamptz not null default now());
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, account_id uuid not null references public.accounts(id) on delete cascade, category_id uuid references public.categories(id), amount numeric(14,2) not null, occurred_at timestamptz not null, label text not null, source text, created_at timestamptz not null default now());
create table if not exists public.budgets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, period_start date not null, period_end date not null, target_end_balance numeric(14,2) not null default 0, created_at timestamptz not null default now());
create table if not exists public.budget_lines (id uuid primary key default gen_random_uuid(), budget_id uuid not null references public.budgets(id) on delete cascade, category_id uuid references public.categories(id), planned_amount numeric(14,2) not null default 0, actual_amount numeric(14,2) not null default 0);
create table if not exists public.goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, target_amount numeric(14,2), current_amount numeric(14,2) not null default 0, target_date date, priority int not null default 50);
create table if not exists public.forecasts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, horizon text not null, scenario text not null, projected_balance numeric(14,2), confidence numeric(5,2), assumptions jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.rules (id uuid primary key default gen_random_uuid(), key text not null unique, description text not null, severity text not null default 'normal', enabled boolean not null default true, version int not null default 1, updated_at timestamptz not null default now());
create table if not exists public.learning_events (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, event_type text not null, before_value jsonb, after_value jsonb, evidence jsonb, created_at timestamptz not null default now());
create table if not exists public.knowledge_sources (id uuid primary key default gen_random_uuid(), url text not null unique, title text, source_type text, trust_score numeric(5,2), last_checked_at timestamptz);
create table if not exists public.knowledge_items (id uuid primary key default gen_random_uuid(), source_id uuid references public.knowledge_sources(id) on delete cascade, title text not null, summary text, kind text not null, published_at timestamptz, confidence numeric(5,2), content_hash text, created_at timestamptz not null default now());
create table if not exists public.recommendations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, type text not null, title text not null, body text not null, status text not null default 'proposed', rule_ids jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table if not exists public.alerts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, severity text not null, title text not null, body text not null, resolved_at timestamptz, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.accounts enable row level security; alter table public.categories enable row level security; alter table public.transactions enable row level security; alter table public.budgets enable row level security; alter table public.goals enable row level security; alter table public.forecasts enable row level security; alter table public.learning_events enable row level security; alter table public.recommendations enable row level security; alter table public.alerts enable row level security;
create policy "profiles own" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "accounts own" on public.accounts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "categories own" on public.categories for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "transactions own" on public.transactions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "budgets own" on public.budgets for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "goals own" on public.goals for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "forecasts own" on public.forecasts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "learning own" on public.learning_events for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "recommendations own" on public.recommendations for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "alerts own" on public.alerts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
